import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for proj in data.get('projects', []):
        proj_name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            fw_name = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw_name)
                pkgs[key] = pkg['resolvedVersion']
        result[proj_name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

print('=== CHANGES ===')
changes = False
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes = True
            print(f'{proj} | {key[0]} ({key[1]}) | {bv} -> {av}')

if not changes:
    print('No changes detected')

print()
print('=== UNCHANGED (sample) ===')
count = 0
for proj in sorted(b.keys()):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(bp.keys()):
        if bp.get(key) == ap.get(key):
            print(f'{proj} | {key[0]} ({key[1]}) | {bp[key]}')
            count += 1
print(f'Total unchanged: {count}')
